    objective, description, beneficiaries, benefits_summary, benefits, eligibility,
    documents, process, deadline, official_link, contact_info, faqs, ai_score,
    ai_checklist, estimated_benefit, target_occupations, target_sectors, max_income, is_active
) VALUES (
    'SCH-FIN-0809DA', 'national-welfare-scheme-173-finance', 'National Welfare Scheme 173 (Finance)', 'Finance', 'Ministry of Finance', 'Central Government',
    'All India', 'Applications Open', 'Empower eligible beneficiaries in All India under Finance with structured financial grants, institutional support, and sector incentives.', 'This scheme aims to empower eligible citizens under the finance domain by offering structured monetary assistance, skill enhancement programs, and direct developmental benefits.', 'Low-to-middle income households, unbanked citizens, and micro-investors.', 'Provides financial grants and support resources for the finance sector.',
    '[{"title": "Direct Financial Assistance", "desc": "Provides financial grants and support resources for the finance sector.", "icon": "rupee"}, {"title": "Sector Development Incentives", "desc": "Structured support, skill training, and capacity-building resources.", "icon": "award"}, {"title": "Direct Bank Disbursal", "desc": "100% electronic transfer directly via Aadhaar-seeded bank account.", "icon": "shield"}]'::jsonb, '["Indian citizen residing in the specified state coverage area.", "Annual family income within prescribed welfare limits.", "Active bank account linked with Aadhaar for DBT transfer.", "Valid identity and domicile verification documentation."]'::jsonb, '["Aadhaar Card", "PAN Card", "Income Certificate", "Bank Passbook / Cancelled Cheque", "Address Proof"]'::jsonb, '[{"title": "Online Registration", "desc": "Register on the official portal with Aadhaar and mobile verification."}, {"title": "Application Filing", "desc": "Fill the electronic form and upload required supporting credentials."}, {"title": "Departmental Scrutiny", "desc": "State and central welfare officers verify submitted details and eligibility."}, {"title": "Sanction & Approval", "desc": "Digital approval letter issued upon successful scrutiny."}, {"title": "Direct Benefit Transfer", "desc": "Sanctioned grant or subsidy credited directly to beneficiary bank account via DBT."}]'::jsonb, '31 Dec 2026',
    'https://www.myscheme.gov.in/', '{"helpline": "1800-11-0001", "email": "support.welfare@gov.in"}'::jsonb, '[{"q": "Who is eligible for National Welfare Scheme 173 (Finance)?", "a": "Citizens residing in All India matching the Finance category parameters and income thresholds are eligible to apply."}, {"q": "How is the benefit amount disbursed?", "a": "All financial grants and subsidies are credited directly into your verified bank account via Direct Benefit Transfer (DBT)."}, {"q": "What documents are required?", "a": "Key documents include Aadhaar Card, PAN Card, Income Certificate."}]'::jsonb, 92,
    '[{"label": "Income Criteria Matched", "pass": true}, {"label": "State / UT Domicile Verified", "pass": true}, {"label": "Sector Eligibility Confirmed", "pass": true}, {"label": "Identity Credentials Ready", "pass": true}]'::jsonb, '₹50,000 – ₹2,00,000 Financial Grant / Subsidy', '["Salaried Employee", "Business Owner", "Daily Wage Worker", "General"]'::jsonb, '["Finance", "Social Welfare", "General"]'::jsonb,
    800000, true
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    ministry = EXCLUDED.ministry,
    benefits_summary = EXCLUDED.benefits_summary,
    description = EXCLUDED.description,
    state_coverage = EXCLUDED.state_coverage,
    is_active = true;
INSERT INTO api_scheme (
    scheme_code, slug, name, category, ministry, gov_level, state_coverage, status,
