    objective, description, beneficiaries, benefits_summary, benefits, eligibility,
    documents, process, deadline, official_link, contact_info, faqs, ai_score,
    ai_checklist, estimated_benefit, target_occupations, target_sectors, max_income, is_active
) VALUES (
    'SCH-HEA-F67B30', 'national-welfare-scheme-377-health', 'National Welfare Scheme 377 (Health)', 'Health', 'Ministry of Finance', 'State Government',
    'Gujarat', 'Applications Open', 'Empower eligible beneficiaries in Gujarat under Health with structured financial grants, institutional support, and sector incentives.', 'This scheme aims to empower eligible citizens under the health domain by offering structured monetary assistance, skill enhancement programs, and direct developmental benefits.', 'Vulnerable families, senior citizens, women, and unorganised sector workers needing healthcare coverage.', 'Provides financial grants and support resources for the health sector.',
    '[{"title": "Direct Financial Assistance", "desc": "Provides financial grants and support resources for the health sector.", "icon": "rupee"}, {"title": "Sector Development Incentives", "desc": "Structured support, skill training, and capacity-building resources.", "icon": "award"}, {"title": "Direct Bank Disbursal", "desc": "100% electronic transfer directly via Aadhaar-seeded bank account.", "icon": "shield"}]'::jsonb, '["Citizen household residing in the covered state or All India.", "Family classified under priority/deprivation categories or low-income threshold.", "Aadhaar seeded with public distribution / health registry.", "No existing comprehensive corporate healthcare coverage."]'::jsonb, '["Aadhaar Card", "Ration Card / BPL Card", "Income Certificate", "Bank Account Details", "Disability / Medical Certificate (if applicable)"]'::jsonb, '[{"title": "Online Registration", "desc": "Register on the official portal with Aadhaar and mobile verification."}, {"title": "Application Filing", "desc": "Fill the electronic form and upload required supporting credentials."}, {"title": "Departmental Scrutiny", "desc": "State and central welfare officers verify submitted details and eligibility."}, {"title": "Sanction & Approval", "desc": "Digital approval letter issued upon successful scrutiny."}, {"title": "Direct Benefit Transfer", "desc": "Sanctioned grant or subsidy credited directly to beneficiary bank account via DBT."}]'::jsonb, '31 Dec 2026',
    'https://www.myscheme.gov.in/', '{"helpline": "1800-11-0001", "email": "support.welfare@gov.in"}'::jsonb, '[{"q": "Who is eligible for National Welfare Scheme 377 (Health)?", "a": "Citizens residing in Gujarat matching the Health category parameters and income thresholds are eligible to apply."}, {"q": "How is the benefit amount disbursed?", "a": "All financial grants and subsidies are credited directly into your verified bank account via Direct Benefit Transfer (DBT)."}, {"q": "What documents are required?", "a": "Key documents include Aadhaar Card, Ration Card / BPL Card, Income Certificate."}]'::jsonb, 98,
    '[{"label": "Income Criteria Matched", "pass": true}, {"label": "State / UT Domicile Verified", "pass": true}, {"label": "Sector Eligibility Confirmed", "pass": true}, {"label": "Identity Credentials Ready", "pass": true}]'::jsonb, '₹1,00,000 – ₹5,00,000 Cashless Health Cover / year', '["Daily Wage Worker", "Farmer", "Unemployed", "General", "Salaried Employee"]'::jsonb, '["Health", "Social Welfare", "General"]'::jsonb,
    600000, true
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    ministry = EXCLUDED.ministry,
    benefits_summary = EXCLUDED.benefits_summary,
    description = EXCLUDED.description,
    state_coverage = EXCLUDED.state_coverage,
    is_active = true;
